export const GLOSSARY_SHARD = Object.freeze({"tokenomics":{"slug":"tokenomics","cat":"basics","en":"Tokenomics","contentLocale":"vi","term":"Tokenomics (kinh tế học token)","aka":["kinh tế học token","mô hình token","token economics"],"short":"Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó.","body":["Khi đọc tokenomics, hãy bắt đầu với các câu hỏi: tổng cung tối đa là bao nhiêu, bao nhiêu phần trăm đang lưu hành, đội ngũ và quỹ đầu tư nắm bao nhiêu, và khi nào họ được bán. Một token mà phần lớn nguồn cung thuộc người trong cuộc có thể chịu áp lực bán lớn khi mở khóa.",["Phía cầu cũng quan trọng: token dùng để trả phí, ",["staking","staking"],", quản trị, hay chỉ để đầu cơ? Một số dự án dùng cơ chế ",["đốt token","token-burn"]," hoặc chia doanh thu cho người staking. Lạm phát cao để trả thưởng staking có thể làm loãng giá trị của người không stake."],"Tokenomics tốt không đảm bảo giá tăng, nhưng tokenomics kém thường tạo rủi ro rõ ràng. Thông tin nằm trong tài liệu chính thức (whitepaper, docs) và các trang theo dõi lịch mở khóa."],"example":["Một token có tổng cung 1 tỷ, phân bổ: cộng đồng và ",["airdrop","airdrop"]," 30%, đội ngũ 20%, nhà đầu tư 25%, quỹ hệ sinh thái 25%. Lúc ",["niêm yết","token-listing"]," lưu hành 12%. Phần đội ngũ và nhà đầu tư, tổng 450 triệu token, bị khóa 12 tháng rồi mở dần trong 24 tháng, tức khoảng 18,75 triệu token mỗi tháng. Với lưu hành ban đầu 120 triệu, chỉ riêng tháng mở khóa đầu tiên đã tăng nguồn cung khoảng 15,6%."],"mistakes":["Bỏ qua phần phân bổ cho đội ngũ và nhà đầu tư vì chỉ đọc phần giới thiệu sản phẩm.","Tin rằng cơ chế đốt token chắc chắn làm giá tăng.","Nghĩ rằng lãi staking cao là thu nhập thật mà không tính đến lạm phát token."],"faq":[{"q":"Tokenomics tốt cần có gì?","a":"Thường là phân bổ minh bạch, tỷ lệ cho người trong cuộc hợp lý, lịch mở khóa rõ ràng và token có công dụng thực tế. Không có công thức chung cho mọi dự án."},{"q":"Xem tokenomics ở đâu?","a":"Trong whitepaper hoặc tài liệu chính thức của dự án, cùng các trang dữ liệu theo dõi nguồn cung và lịch mở khóa token."}],"title":"Tokenomics là gì? Cách đọc kinh tế học token","description":"Tokenomics là gì, cách đọc tổng cung, phân bổ và lịch mở khóa token, và những dấu hiệu cảnh báo cần chú ý.","related":[["circulating-supply","Nguồn cung lưu hành (Circulating supply)","Nguồn cung lưu hành (circulating supply) là số lượng coin hoặc token đang thực sự có trên thị trường và có thể giao dịch, không tính phần bị khóa, chưa phát hành hoặc đã bị đốt."],["token-unlock","Mở khóa token (Token unlock)","Mở khóa token (token unlock) là thời điểm một lượng token trước đây bị khóa theo lịch vesting được phép chuyển và bán, thường là phần của đội ngũ, nhà đầu tư hoặc quỹ dự án."],["fully-diluted-valuation","Định giá pha loãng hoàn toàn (FDV)","Định giá pha loãng hoàn toàn (FDV) là giá hiện tại của token nhân với tổng cung tối đa, cho biết dự án sẽ được định giá bao nhiêu nếu toàn bộ token đã được phát hành."],["token-burn","Đốt token (Token burn)","Đốt token (token burn) là việc gửi token tới một địa chỉ không ai có thể truy cập hoặc hủy chúng bằng hợp đồng, khiến lượng token đó bị loại vĩnh viễn khỏi nguồn cung."],["governance-token","Token quản trị (Governance token)","Token quản trị là token cho người nắm giữ quyền đề xuất và bỏ phiếu về các thay đổi của một giao thức hay DAO, ví dụ UNI của Uniswap hay AAVE của Aave."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"order-book":{"slug":"order-book","cat":"trading","en":"Order book","contentLocale":"vi","term":"Sổ lệnh (Order book)","aka":["sổ lệnh","order book","sổ lệnh mua bán"],"short":"Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng.","body":[["Sổ lệnh có hai phía: bên mua (bid), thường màu xanh, gồm các lệnh mua ở giá thấp hơn giá hiện tại; và bên bán (ask), thường màu đỏ, gồm các lệnh bán ở giá cao hơn. Khoảng cách giữa giá mua cao nhất và giá bán thấp nhất là ",["chênh lệch giá mua-bán (spread)","bid-ask-spread"],"."],[["Lệnh giới hạn","limit-order"]," bạn đặt mà chưa khớp ngay sẽ nằm trong sổ lệnh, cung cấp ",["thanh khoản","liquidity"]," (maker). ",["Lệnh thị trường","market-order"]," lấy thanh khoản từ sổ lệnh và khớp ngay với các lệnh tốt nhất ở phía đối diện (taker)."],"Độ sâu sổ lệnh cho biết có bao nhiêu khối lượng ở mỗi mức giá. Sổ lệnh dày giúp lệnh lớn khớp mà giá không trượt nhiều; sổ lệnh mỏng khiến giá dễ bị đẩy. Lưu ý một số lệnh lớn có thể đặt ra rồi rút đi nhanh để tạo ảo giác, nên đừng dựa hoàn toàn vào những bức tường lệnh."],"example":["Giả sử sổ lệnh ",["ETH","ethereum"],"/",["USDT","usdt"]," phía bán có: 2 ETH ở 2.001, 3 ETH ở 2.002 và 5 ETH ở 2.004. Bạn đặt lệnh thị trường mua 6 ETH. Lệnh sẽ khớp 2 ETH ở 2.001, 3 ETH ở 2.002 và 1 ETH ở 2.004, tổng 4.002 + 6.006 + 2.004 = 12.012 USDT. Giá trung bình là 12.012 / 6 = 2.002 USDT, cao hơn giá bán tốt nhất 1 USDT mỗi ETH."],"mistakes":["Đặt lệnh thị trường lớn khi sổ lệnh mỏng mà không xem độ sâu.","Tin vào các bức tường lệnh lớn như tín hiệu chắc chắn.","Nhầm phía mua và phía bán khi đọc sổ lệnh lần đầu."],"faq":[{"q":"Sổ lệnh màu xanh và đỏ nghĩa là gì?","a":"Thông thường màu xanh là lệnh mua (bid) và màu đỏ là lệnh bán (ask). Một số sàn cho phép đổi màu trong phần cài đặt."},{"q":"DEX có sổ lệnh không?","a":"Một số DEX dùng sổ lệnh trên chuỗi, như Hyperliquid. Nhiều DEX khác dùng pool thanh khoản với cơ chế tạo lập thị trường tự động (AMM) thay cho sổ lệnh."}],"title":"Sổ lệnh (order book) là gì? Cách đọc","description":"Sổ lệnh là gì, cách đọc phía mua và bán, độ sâu thị trường và vì sao lệnh lớn có thể khớp ở giá trung bình kém hơn.","related":[["bid-ask-spread","Chênh lệch giá mua-bán (Spread)","Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Tại sao giá trên màn hình không phải là giá khớp lệnh của tôi?"},"coin":null,"tool":null,"cta":true},"liquidity":{"slug":"liquidity","cat":"trading","en":"Liquidity","contentLocale":"vi","term":"Thanh khoản (Liquidity)","aka":["liquidity","tính thanh khoản","độ thanh khoản"],"short":"Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều.","body":[["Một ",["cặp giao dịch","trading-pair"]," có thanh khoản tốt khi ",["sổ lệnh","order-book"]," có nhiều lệnh chờ ở cả hai phía, ",["chênh lệch giá mua-bán (spread)","bid-ask-spread"]," hẹp và khối lượng khớp lệnh đều đặn. Khi đó bạn có thể vào hoặc thoát lệnh nhanh với mức giá gần giá bạn thấy trên màn hình."],["Thanh khoản kém thì ngược lại: spread rộng, ít lệnh chờ, và một ",["lệnh thị trường","market-order"]," lớn có thể ăn qua nhiều mức giá, gây ",["trượt giá","slippage"]," đáng kể. Các coin ",["vốn hóa","market-capitalization"]," nhỏ, cặp giao dịch mới niêm yết hoặc giờ thị trường vắng thường có thanh khoản thấp hơn."],"Cùng một coin có thể có thanh khoản rất khác nhau giữa các sàn. Trên sàn phi tập trung, thanh khoản nằm trong pool thanh khoản thay vì sổ lệnh, và độ sâu của pool quyết định mức trượt giá."],"example":"Giả sử bạn muốn bán 5.000 USDT một altcoin. Trên sàn A, sổ lệnh có 20.000 USDT lệnh mua trong phạm vi 0,2% quanh giá hiện tại, nên lệnh của bạn khớp gần như trọn ở giá thị trường. Trên sàn B, chỉ có 3.000 USDT lệnh mua trong phạm vi 1%, phần còn lại phải khớp ở mức thấp hơn 2-3%. Cùng một lệnh, bạn có thể nhận ít hơn khoảng 80-100 USDT chỉ vì thanh khoản ở sàn B mỏng hơn.","mistakes":["Đặt lệnh thị trường lớn cho coin thanh khoản thấp mà không xem độ sâu sổ lệnh.","Coi khối lượng giao dịch cao là bằng chứng chắc chắn của thanh khoản tốt, trong khi khối lượng có thể bị thổi phồng.","Quên rằng thanh khoản có thể biến mất rất nhanh khi thị trường biến động mạnh."],"faq":[{"q":"Thanh khoản trong crypto là gì?","a":"Đó là khả năng mua bán một coin nhanh mà giá không bị lệch nhiều. Thanh khoản tốt đi kèm spread hẹp và sổ lệnh dày."},{"q":"Làm sao biết một coin có thanh khoản tốt?","a":"Bạn xem spread, độ sâu sổ lệnh trong phạm vi 1-2% quanh giá, và khối lượng giao dịch trên nhiều sàn uy tín cùng lúc."}],"title":"Thanh khoản là gì? Ý nghĩa thanh khoản trong crypto","description":"Thanh khoản là gì, vì sao nó ảnh hưởng tới trượt giá và spread, và cách kiểm tra thanh khoản trước khi đặt lệnh lớn.","related":[["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."],["bid-ask-spread","Chênh lệch giá mua-bán (Spread)","Chênh lệch giá mua-bán (bid-ask spread) là khoảng cách giữa giá mua cao nhất (bid) và giá bán thấp nhất (ask) trong sổ lệnh, và là chi phí ngầm mỗi khi bạn mua rồi bán ngay bằng lệnh thị trường."],["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."],["market-maker","Nhà tạo lập thị trường (Market maker)","Nhà tạo lập thị trường (market maker) là cá nhân hoặc tổ chức liên tục đặt lệnh mua và lệnh bán cho một tài sản để cung cấp thanh khoản và kiếm lời từ chênh lệch giá."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Tại sao giá trên màn hình không phải là giá khớp lệnh của tôi?"},"coin":null,"tool":null,"cta":false},"isolated-margin":{"slug":"isolated-margin","cat":"derivatives","en":"Isolated margin","contentLocale":"vi","term":"Ký quỹ cô lập (Isolated margin)","aka":["isolated margin","isolated","margin cô lập"],"short":"Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó.","body":["Khi mở vị thế ở chế độ cô lập, bạn quyết định số ký quỹ dành cho vị thế. Phần số dư còn lại trong tài khoản không bị dùng để cứu vị thế này. Rủi ro tối đa của vị thế được giới hạn rõ ràng.",["Đổi lại, vị thế cô lập dễ ",["bị thanh lý","liquidation"]," hơn so với ",["ký quỹ chéo","cross-margin"],", vì không có số dư khác hỗ trợ. Nếu muốn đẩy ",["giá thanh lý","liquidation-price"]," ra xa, bạn phải tự thêm ký quỹ."],["Chế độ cô lập phù hợp với giao dịch có tính đầu cơ, khi bạn muốn biết chắc mỗi lệnh mất tối đa bao nhiêu. Trên một số sàn và chế độ ",["tài khoản hợp nhất","unified-trading-account"],", cách chuyển giữa cô lập và chéo, cũng như việc có đổi được khi đang có vị thế, là khác nhau."]],"example":["Giả sử tài khoản futures của bạn có 3.000 ",["USDT","usdt"],". Bạn mở long DOGE với ký quỹ cô lập 300 USDT, ",["đòn bẩy","leverage"]," 10x, giá trị vị thế 3.000 USDT. Giá DOGE giảm khoảng 9-10% và vị thế bị thanh lý. Bạn mất khoảng 300 USDT, còn 2.700 USDT trong tài khoản không bị ảnh hưởng."],"mistakes":["Nghĩ rằng ký quỹ cô lập giúp tránh thanh lý, trong khi nó chỉ giới hạn mức lỗ.","Liên tục thêm ký quỹ vào vị thế cô lập, biến nó thành vị thế lớn hơn dự định.","Quên kiểm tra chế độ ký quỹ mặc định trước khi mở lệnh."],"faq":[{"q":"Nên dùng ký quỹ cô lập hay chéo?","a":"Cô lập phù hợp khi bạn muốn giới hạn lỗ từng lệnh. Chéo phù hợp khi bạn quản lý nhiều vị thế bù trừ nhau và theo dõi chặt tài khoản."},{"q":"Ký quỹ cô lập có mất hết tài khoản không?","a":"Không, khi bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó. Số dư còn lại vẫn an toàn với vị thế này."}],"title":"Ký quỹ cô lập (isolated margin) là gì?","description":"Ký quỹ cô lập là gì, cách nó giới hạn mức lỗ cho từng vị thế và khi nào nên dùng thay vì ký quỹ chéo.","related":[["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản."],["portfolio-margin","Ký quỹ danh mục (Portfolio margin)","Ký quỹ danh mục là chế độ tính ký quỹ dựa trên rủi ro tổng thể của cả danh mục, cho phép các vị thế phòng hộ lẫn nhau được giảm yêu cầu ký quỹ."],["liquidation-price","Giá thanh lý (Liquidation price)","Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."]],"lesson":{"id":"E21","slug":"isolated-margin","ep":21,"title":"Ký quỹ cô lập: đặt giao dịch này vào chiếc hộp riêng biệt"},"coin":null,"tool":null,"cta":false},"index-price":{"slug":"index-price","cat":"derivatives","en":"Index price","contentLocale":"vi","term":"Giá chỉ số (Index price)","aka":["index price","giá index","chỉ số giá"],"short":"Giá chỉ số (index price) là giá trung bình có trọng số của một tài sản trên nhiều sàn spot lớn, được dùng làm tham chiếu cho giá đánh dấu và funding rate.","body":[["Sàn chọn một rổ các sàn spot có ",["thanh khoản","liquidity"]," tốt và tính giá trung bình, thường gán trọng số và loại bỏ các nguồn lệch bất thường. Kết quả là một mức giá phản ánh thị trường rộng hơn, khó bị thao túng bởi một sàn đơn lẻ."],["Giá chỉ số là nền tảng của ",["giá đánh dấu","mark-price"],". ",["Funding rate","funding-rate"]," cũng được tính dựa trên chênh lệch giữa giá hợp đồng perp và giá chỉ số. Hợp đồng giao sau thường được tất toán theo giá chỉ số trung bình gần thời điểm đáo hạn."],["Thành phần rổ, trọng số và cách xử lý nguồn lỗi khác nhau giữa các sàn và thường được công bố trên trang thông số hợp đồng. Trên ",["DEX phái sinh","perp-dex"],", vai trò tương tự do ",["oracle","oracle"]," đảm nhận."]],"example":["Giả sử giá ",["BTC","bitcoin"]," trên bốn sàn spot là 65.000, 65.040, 64.980 và 65.020 USDT, với trọng số bằng nhau. Giá chỉ số là (65.000 + 65.040 + 64.980 + 65.020) / 4 = 65.010 USDT. Nếu một sàn bất ngờ báo 63.000 USDT do sự cố, quy tắc loại nguồn lệch có thể bỏ giá đó ra và chỉ dùng ba sàn còn lại."],"mistakes":["Nghĩ rằng giá chỉ số là giá spot trên chính sàn bạn dùng.","So sánh giá perp với giá spot một sàn để đoán funding thay vì với giá chỉ số.","Bỏ qua việc thành phần chỉ số có thể thay đổi theo thời gian."],"faq":[{"q":"Index price là gì?","a":"Là giá trung bình của một tài sản trên nhiều sàn spot. Sàn dùng nó làm nền cho giá đánh dấu, funding và giá tất toán."},{"q":"Vì sao index price khác giá spot trên sàn?","a":"Vì nó là trung bình nhiều nguồn, nên có thể lệch nhẹ so với giá ở một sàn cụ thể, nhất là khi thị trường biến động nhanh."}],"title":"Index price (giá chỉ số) là gì trong futures?","description":"Giá chỉ số là gì, sàn tính index price từ nhiều sàn spot thế nào và vai trò của nó với mark price, funding rate.","related":[["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."],["last-price","Giá giao dịch cuối (Last price)","Giá giao dịch cuối (last price) là mức giá của lệnh khớp gần nhất trên sổ lệnh của một sàn, chính là con số giá bạn thấy thay đổi liên tục trên ứng dụng."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["oracle","Oracle (Nguồn dữ liệu blockchain)","Oracle là dịch vụ đưa dữ liệu bên ngoài như giá tài sản, kết quả sự kiện hay số ngẫu nhiên vào blockchain để hợp đồng thông minh sử dụng."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Thanh lý: ai đã nhấn nút buộc đóng vị thế?"},"coin":null,"tool":"/funding-rates","cta":false},"yield-farming":{"slug":"yield-farming","cat":"defi","en":"Yield farming","contentLocale":"vi","term":"Yield farming (Canh tác lợi suất)","aka":["yield farming","farm","canh tác lợi suất","farming"],"short":"Yield farming là chiến lược đưa crypto vào các giao thức DeFi như pool thanh khoản hoặc nền tảng cho vay để nhận phí, lãi và token thưởng, thường di chuyển vốn tới nơi trả lợi suất cao.","body":[["Một vòng farm điển hình: góp ",["thanh khoản","liquidity"]," vào ",["DEX","dex"],", nhận token LP, rồi đem token LP stake vào hợp đồng farm để nhận thêm ",["token quản trị","governance-token"]," của dự án. Một số người lặp lại nhiều lớp, ví dụ vay thêm trên tài sản đang farm để tăng quy mô."],[["APR","apr-vs-apy"]," hiển thị trên farm thường gồm hai phần: phí thật từ người giao dịch hoặc người vay, và token thưởng được phát hành thêm. Phần thưởng hay chiếm tỷ trọng lớn, nhưng nếu nhiều người bán token thưởng, giá giảm và lợi suất thực tế co lại."],["Rủi ro cộng dồn theo từng lớp: lỗi hợp đồng, ",["tổn thất tạm thời","impermanent-loss"],", ",["thanh lý","liquidation"]," nếu có vay, token thưởng mất giá, và phí gas khi vào ra liên tục."]],"example":"Giả sử bạn đưa 5.000 USD vào một farm hiển thị APR 40%, trong đó 10% từ phí giao dịch và 30% từ token thưởng. Sau một năm, phí mang lại 500 USD. Token thưởng tính theo giá lúc phát là 1.500 USD, nhưng giá token giảm một nửa nên chỉ còn 750 USD. Tổng thu thực tế là 1.250 USD, tức 25%, chưa trừ tổn thất tạm thời và phí gas.","mistakes":["Tin rằng APR hiển thị là lợi nhuận chắc chắn trong cả năm.","Giữ token thưởng mà không để ý giá của nó đang giảm liên tục do bị bán ra.","Farm trên giao thức mới chưa kiểm toán chỉ vì APR ba chữ số."],"faq":[{"q":"Yield farming khác staking thế nào?","a":"Staking thường là khóa coin để bảo vệ mạng blockchain và nhận thưởng. Yield farming là tìm lợi suất qua nhiều giao thức DeFi, thường kèm rủi ro tổn thất tạm thời và rủi ro hợp đồng."},{"q":"Vì sao APR farm giảm nhanh?","a":"Khi nhiều vốn đổ vào, phần thưởng bị chia cho nhiều người hơn, và giá token thưởng thường giảm khi người farm bán ra."}],"title":"Yield farming là gì? Cách canh tác lợi suất DeFi","description":"Yield farming là gì, lợi suất đến từ đâu, vì sao APR hiển thị khác lợi nhuận thực và những rủi ro khi farm DeFi.","related":[["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."],["apr-vs-apy","APR và APY","APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn."],["impermanent-loss","Tổn thất tạm thời (Impermanent loss)","Tổn thất tạm thời là phần giá trị bạn bị thiệt khi cung cấp thanh khoản cho pool so với việc chỉ giữ nguyên hai token, phát sinh khi giá của chúng thay đổi lệch nhau."],["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"mev":{"slug":"mev","cat":"defi","en":"MEV (maximal extractable value)","contentLocale":"vi","term":"MEV (Giá trị khai thác tối đa)","aka":["MEV","maximal extractable value","sandwich attack","front-running"],"short":"MEV là phần lợi nhuận mà người sắp xếp giao dịch trong khối, như validator hay bot tìm kiếm, có thể thu được bằng cách chèn, sắp xếp lại hoặc loại bỏ giao dịch.","body":[["Giao dịch của bạn trước khi vào khối thường nằm công khai trong ",["mempool","mempool"],". Bot theo dõi mempool có thể thấy lệnh swap lớn của bạn và chen giao dịch của chúng vào trước hoặc sau để kiếm lời. Kiểu phổ biến nhất là tấn công sandwich: mua ngay trước bạn để đẩy giá, rồi bán ngay sau bạn."],["Không phải MEV nào cũng có hại. ",["Arbitrage","arbitrage"]," giữa các ",["DEX","dex"]," giúp giá đồng đều, và ",["thanh lý","liquidation"]," nhanh giúp giao thức cho vay không bị nợ xấu. Nhưng sandwich trực tiếp lấy tiền từ người dùng qua giá khớp xấu hơn."],["Cách giảm thiểu: đặt mức ",["trượt giá","slippage"]," chấp nhận thấp và hợp lý, chia lệnh lớn, dùng RPC hoặc tính năng gửi giao dịch riêng tư chống MEV mà một số ví hỗ trợ, hoặc dùng DEX tổng hợp có cơ chế bảo vệ."]],"example":["Giả sử bạn mua token bằng 5.000 ",["USDC","usdc"]," trên DEX với trượt giá tối đa 3%. Bot thấy lệnh, mua trước làm giá tăng 2,5%, lệnh của bạn vẫn khớp vì chưa vượt 3%, rồi bot bán ngay sau. Bạn nhận ít token hơn khoảng 2,5%, tương đương khoảng 125 USDC. Nếu bạn đặt trượt giá 0,5%, lệnh sẽ bị hủy thay vì bị kẹp, và bạn chỉ mất phí gas."],"mistakes":["Đặt trượt giá rất cao để lệnh “chắc khớp”, tạo khoảng trống cho bot sandwich.","Swap số lớn trong pool mỏng qua mempool công khai.","Nghĩ rằng chỉ người giao dịch lớn mới bị MEV ảnh hưởng."],"faq":[{"q":"Sandwich attack là gì?","a":"Là khi bot đặt một lệnh mua ngay trước lệnh của bạn và một lệnh bán ngay sau, ăn phần chênh lệch giá mà lệnh của bạn tạo ra."},{"q":"Giao dịch trên sàn tập trung có bị MEV không?","a":"MEV theo nghĩa on-chain chủ yếu xảy ra trên blockchain và DEX. Lệnh trên sổ lệnh nội bộ của sàn tập trung không đi qua mempool công khai."}],"title":"MEV là gì? Sandwich attack và cách tự bảo vệ","description":"MEV là gì, bot sandwich chạy trước lệnh của bạn thế nào, MEV nào có lợi, MEV nào có hại và cách giảm thiệt hại khi swap.","related":[["mempool","Mempool (vùng chờ giao dịch)","Mempool là nơi các giao dịch đã được phát lên mạng nhưng chưa được đưa vào khối nằm chờ, trước khi thợ đào hoặc validator chọn để xác nhận."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."],["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"nft":{"slug":"nft","cat":"defi","en":"NFT (non-fungible token)","contentLocale":"vi","term":"NFT (Token không thể thay thế)","aka":["NFT","non-fungible token","token không thể thay thế"],"short":"NFT là token độc nhất trên blockchain, mỗi token có mã định danh riêng và không thể đổi ngang với token khác, thường dùng để đại diện cho tác phẩm số, vật phẩm game, vé hoặc tư cách thành viên.","body":[["Một ",["USDT","usdt"]," luôn đổi được với một USDT khác, đó là tính có thể thay thế. NFT thì mỗi chiếc khác nhau. Trên ",["Ethereum","ethereum"],", NFT theo chuẩn ERC-721 hoặc ERC-1155; Solana, ",["Bitcoin","bitcoin"]," và nhiều chuỗi khác cũng có NFT. ",["Blockchain","blockchain"]," ghi ai sở hữu token, còn hình ảnh thường được lưu ở nơi khác như IPFS hoặc máy chủ của dự án."],["Sở hữu NFT không tự động có nghĩa là sở hữu bản quyền tác phẩm; quyền sử dụng tùy điều khoản của từng dự án. Giá NFT phụ thuộc mạnh vào cộng đồng và nhu cầu, ",["thanh khoản","liquidity"]," thường mỏng, nên bán nhanh có thể phải chấp nhận giá thấp."],["NFT cũng là kênh lừa đảo phổ biến: mint giả, NFT ",["airdrop","airdrop"]," lạ dẫn tới trang lấy quyền ví, và yêu cầu ký setApprovalForAll cho phép lấy toàn bộ bộ sưu tập."]],"example":"Giả sử bạn mua một NFT với giá 0,5 ETH. Giá sàn của bộ sưu tập, tức giá chào bán thấp nhất, là 0,5 ETH. Khi cần bán gấp, giá sàn đã xuống 0,3 ETH và lệnh đặt mua cao nhất chỉ 0,26 ETH. Nếu bán ngay, sau phí sàn giao dịch NFT ví dụ 2,5%, bạn nhận khoảng 0,2535 ETH, lỗ gần một nửa tính theo ETH.","mistakes":["Bấm vào NFT lạ tự xuất hiện trong ví rồi kết nối với trang web mà nó dẫn tới.","Ký setApprovalForAll cho trang không rõ nguồn gốc.","Định giá NFT theo giao dịch cao nhất thay vì giá sàn và lệnh mua thực tế."],"faq":[{"q":"Mua NFT có phải mua bản quyền hình ảnh không?","a":"Không nhất thiết. Bạn sở hữu token, còn quyền với tác phẩm tùy điều khoản do dự án công bố."},{"q":"Giá sàn NFT là gì?","a":"Là giá chào bán thấp nhất của một bộ sưu tập trên sàn giao dịch NFT, thường được dùng để ước lượng giá trị của các NFT phổ thông trong bộ đó."}],"title":"NFT là gì? Token không thể thay thế giải thích dễ hiểu","description":"NFT là gì, hoạt động ra sao trên blockchain, sở hữu NFT có nghĩa là gì, giá sàn và các chiêu lừa đảo NFT cần tránh.","related":[["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["token-approval","Cấp quyền token (Token approval)","Cấp quyền token là thao tác cho phép một hợp đồng thông minh được chi tiêu một lượng token nhất định trong ví của bạn, bắt buộc trước khi swap hay gửi token vào nhiều ứng dụng DeFi."],["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["coin-vs-token","Coin và token (Coin vs token)","Coin là tài sản gốc của một blockchain riêng như BTC hay ETH, còn token là tài sản được tạo trên một blockchain có sẵn thông qua hợp đồng thông minh, như USDT trên Ethereum hay Tron."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"vasp":{"slug":"vasp","cat":"regulation","en":"VASP (virtual asset service provider)","contentLocale":"vi","term":"VASP (nhà cung cấp dịch vụ tài sản ảo)","aka":["VASP","nhà cung cấp dịch vụ tài sản ảo","CASP"],"short":"VASP là tổ chức cung cấp dịch vụ liên quan đến tài sản ảo cho người khác, như sàn giao dịch, dịch vụ lưu ký hoặc chuyển đổi crypto, và chịu các nghĩa vụ quản lý như KYC, AML.","body":[["Thuật ngữ VASP được FATF dùng để chỉ những doanh nghiệp trao đổi crypto với tiền pháp định, trao đổi giữa các crypto, chuyển hoặc lưu ký tài sản ảo thay mặt khách hàng. Ở EU, khái niệm tương tự trong ",["MiCA","mica"]," được gọi là CASP."],["Tại nhiều quốc gia, VASP phải đăng ký hoặc xin giấy phép, thực hiện ",["KYC","kyc"],", giám sát giao dịch và tuân thủ ",["travel rule","travel-rule"],". Cùng một thương hiệu sàn có thể hoạt động qua nhiều pháp nhân khác nhau, mỗi pháp nhân được cấp phép ở một nơi."],"Khi chọn sàn, hãy kiểm tra pháp nhân nào phục vụ quốc gia của bạn và giấy phép đó có hiệu lực ở đâu. Tại Việt Nam, khung pháp lý cho tài sản mã hóa vẫn đang được hoàn thiện, nên hãy theo dõi văn bản chính thức của cơ quan nhà nước."],"example":["Giả sử sàn X có ba pháp nhân: một được cấp phép CASP ở một nước EU, một đăng ký ở Dubai và một ở khu vực khác. Khi bạn mở tài khoản từ Việt Nam, điều khoản dịch vụ ghi bạn được phục vụ bởi pháp nhân thứ ba. Giấy phép EU vì vậy không trực tiếp bảo vệ tài khoản của bạn. Nếu có tranh chấp về khoản 5.000 ",["USDT","usdt"]," bị giữ, luật áp dụng là luật nơi pháp nhân thứ ba đăng ký."],"mistakes":["Thấy sàn có một giấy phép ở đâu đó rồi cho rằng mọi người dùng toàn cầu đều được bảo vệ như nhau.","Không đọc điều khoản để biết pháp nhân nào đang giữ tài sản của mình.","Nhầm lẫn giữa đăng ký đơn giản và giấy phép hoạt động đầy đủ."],"faq":[{"q":"VASP và CASP khác nhau không?","a":"Về ý nghĩa thì gần giống nhau. VASP là thuật ngữ của FATF, còn CASP là thuật ngữ trong MiCA của EU với yêu cầu cấp phép cụ thể."},{"q":"Làm sao kiểm tra một sàn có phải VASP được cấp phép?","a":"Tra cứu danh sách công khai của cơ quan quản lý tại quốc gia đó và đối chiếu tên pháp nhân trong điều khoản dịch vụ của sàn."}],"title":"VASP là gì? Nhà cung cấp dịch vụ tài sản ảo","description":"VASP là sàn hoặc dịch vụ crypto chịu quản lý KYC, AML. Hiểu VASP, CASP, giấy phép theo pháp nhân và cách kiểm tra sàn.","related":[["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["mica","MiCA (Luật thị trường tài sản mã hóa của EU)","MiCA là bộ quy định chung của Liên minh châu Âu về tài sản mã hóa, đặt ra yêu cầu cấp phép cho nhà cung cấp dịch vụ và quy tắc riêng cho stablecoin."],["travel-rule","Travel rule (quy tắc chuyển tiền)","Travel rule là quy định yêu cầu các nhà cung cấp dịch vụ tài sản ảo gửi kèm thông tin người gửi và người nhận khi chuyển crypto giữa các tổ chức với nhau."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Tìm đúng cửa chính thức: Đừng mở tài khoản một cách mù quáng"},"coin":null,"tool":"/topics/compliant-exchanges","cta":false},"mica":{"slug":"mica","cat":"regulation","en":"MiCA (EU Markets in Crypto-Assets)","contentLocale":"vi","term":"MiCA (Luật thị trường tài sản mã hóa của EU)","aka":["MiCA","MiCAR","Markets in Crypto-Assets"],"short":"MiCA là bộ quy định chung của Liên minh châu Âu về tài sản mã hóa, đặt ra yêu cầu cấp phép cho nhà cung cấp dịch vụ và quy tắc riêng cho stablecoin.","body":[["MiCA áp dụng theo hai giai đoạn. Phần dành cho ",["stablecoin","stablecoin"],", gồm token tham chiếu tài sản và token ",["tiền điện tử","cryptocurrency"],", có hiệu lực từ ngày 30 tháng 6 năm 2024. Phần dành cho nhà cung cấp dịch vụ tài sản mã hóa, gọi là ",["CASP","vasp"],", có hiệu lực từ ngày 30 tháng 12 năm 2024, kèm thời gian chuyển tiếp của từng quốc gia kéo dài tối đa tới ngày 1 tháng 7 năm 2026."],"Một CASP được cấp phép ở một nước thành viên có thể phục vụ khách hàng trên toàn EU theo cơ chế passport. Nhà phát hành stablecoin phải có giấy phép, giữ dự trữ theo quy định và công bố thông tin. Vì vậy một số sàn đã hạn chế các stablecoin chưa tuân thủ cho người dùng EU.",["Nếu bạn không sống ở EU, MiCA không trực tiếp áp dụng, nhưng nó ảnh hưởng tới cách các sàn lớn thiết kế sản phẩm, danh sách stablecoin và quy trình ",["KYC","kyc"]," trên toàn cầu."]],"example":["Giả sử bạn là người Việt sống ở Đức và đang giữ 5.000 ",["USDT","usdt"]," trên một sàn đã có giấy phép CASP. Sàn thông báo hạn chế giao dịch một số cặp USDT cho người dùng EU vì stablecoin đó chưa đáp ứng MiCA. Bạn vẫn rút được USDT, hoặc có thể đổi sang stablecoin tuân thủ như ",["USDC","usdc"]," hoặc EURC. Nếu phí chuyển đổi là 0,1%, đổi 5.000 USDT tốn khoảng 5 USD."],"mistakes":["Nghĩ MiCA cấm crypto ở châu Âu, trong khi nó tạo khung cấp phép để hoạt động hợp pháp.","Cho rằng mọi sàn có người dùng EU đều đã có giấy phép CASP.","Hoảng loạn bán stablecoin khi sàn chỉ hạn chế giao dịch chứ không khóa tài sản."],"faq":[{"q":"MiCA có áp dụng cho người Việt Nam không?","a":"MiCA áp dụng cho dịch vụ cung cấp tại EU. Người sống ở Việt Nam không trực tiếp chịu MiCA, nhưng có thể thấy thay đổi sản phẩm từ các sàn toàn cầu."},{"q":"USDT có bị cấm theo MiCA không?","a":"MiCA không cấm người dùng nắm giữ, nhưng các CASP tại EU bị hạn chế cung cấp stablecoin chưa có giấy phép phù hợp, nên nhiều sàn đã giới hạn USDT cho khách EU."}],"title":"MiCA là gì? Luật crypto của Liên minh châu Âu","description":"MiCA là khung pháp lý crypto của EU. Tìm hiểu mốc hiệu lực, giấy phép CASP, quy định stablecoin và ảnh hưởng tới người dùng.","related":[["vasp","VASP (nhà cung cấp dịch vụ tài sản ảo)","VASP là tổ chức cung cấp dịch vụ liên quan đến tài sản ảo cho người khác, như sàn giao dịch, dịch vụ lưu ký hoặc chuyển đổi crypto, và chịu các nghĩa vụ quản lý như KYC, AML."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["usdc","USDC (USD Coin)","USDC là stablecoin do công ty Circle phát hành, neo 1:1 với đô la Mỹ và được đảm bảo bằng tiền mặt cùng tài sản ngắn hạn tương đương tiền."],["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Tìm đúng cửa chính thức: Đừng mở tài khoản một cách mù quáng"},"coin":null,"tool":null,"cta":false},"dual-investment":{"slug":"dual-investment","cat":"exchange-features","en":"Dual investment","contentLocale":"vi","term":"Đầu tư kép (dual investment)","aka":["dual investment","đầu tư kép","dual asset","sản phẩm lãi kép đôi"],"short":"Đầu tư kép là sản phẩm có cấu trúc cho lợi suất cao trong thời gian ngắn, nhưng khi đáo hạn bạn có thể nhận lại tài sản ban đầu hoặc một tài sản khác tùy giá so với giá mục tiêu.","body":[["Có hai chiều. Mua thấp: bạn gửi ",["stablecoin","stablecoin"],", chọn giá mục tiêu thấp hơn giá hiện tại. Nếu khi đáo hạn giá dưới mục tiêu, bạn được chuyển sang coin với giá mục tiêu. Bán cao: bạn gửi coin, chọn giá mục tiêu cao hơn. Nếu giá vượt mục tiêu, coin của bạn được bán thành stablecoin."],["Về bản chất, bạn đang bán ",["quyền chọn","options"]," và nhận phí quyền chọn dưới dạng lãi suất. Lợi suất cao vì bạn chấp nhận rủi ro bị đổi tài sản ở mức giá kém hơn thị trường khi giá ",["biến động","volatility"]," mạnh."],"Bạn không thể rút giữa kỳ, và lợi suất được tính theo năm nên con số thực nhận cho vài ngày thường nhỏ. Tên sản phẩm, kỳ hạn và giờ thanh toán khác nhau giữa các sàn."],"example":["Giả sử ",["BTC","bitcoin"]," đang ở 60.000 ",["USDT","usdt"],". Bạn gửi 1.000 USDT vào sản phẩm mua thấp với giá mục tiêu 57.000, kỳ hạn 7 ngày, ",["APR","apr-vs-apy"]," 30%. Tiền lãi là 1.000 nhân 30% nhân 7 chia 365, khoảng 5,75 USDT. Nếu khi đáo hạn BTC trên 57.000, bạn nhận 1.005,75 USDT. Nếu BTC xuống 52.000, bạn nhận khoảng 0,01764 BTC, tức 1.005,75 chia 57.000, và giá trị lúc đó chỉ khoảng 917 USDT."],"mistakes":["Nhìn APR 30% hay 100% mà quên rằng đó là lãi tính theo năm cho kỳ hạn vài ngày.","Chọn mua thấp với coin mà bạn không thực sự muốn nắm giữ.","Coi đầu tư kép là gửi tiết kiệm có bảo toàn vốn."],"faq":[{"q":"Đầu tư kép có lỗ được không?","a":"Có thể lỗ khi quy đổi theo giá thị trường. Bạn luôn nhận lãi, nhưng nếu bị đổi sang tài sản khác ở giá mục tiêu, giá trị thực tế có thể thấp hơn số vốn ban đầu."},{"q":"Nên chọn giá mục tiêu thế nào?","a":"Chọn mức giá mà bạn thật sự sẵn lòng mua hoặc bán. Giá mục tiêu càng gần giá hiện tại thì lãi càng cao nhưng khả năng bị đổi tài sản cũng càng lớn."}],"title":"Đầu tư kép là gì? Dual investment hoạt động thế nào","description":"Đầu tư kép trả lãi cao nhưng có thể đổi tài sản khi đáo hạn. Tìm hiểu mua thấp, bán cao, cách tính lãi và rủi ro.","related":[["options","Quyền chọn crypto (Options)","Quyền chọn crypto là hợp đồng cho người mua quyền, nhưng không bắt buộc, mua (call) hoặc bán (put) một tài sản ở mức giá định trước trong hoặc tại một thời điểm định trước."],["crypto-earn","Earn (sản phẩm tiết kiệm crypto)","Earn là nhóm sản phẩm trên sàn cho phép bạn gửi crypto để nhận lãi, gồm gửi linh hoạt, gửi kỳ hạn, staking và các sản phẩm có cấu trúc."],["apr-vs-apy","APR và APY","APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."]],"lesson":null,"coin":null,"tool":null,"cta":false},"unified-trading-account":{"slug":"unified-trading-account","cat":"exchange-features","en":"Unified trading account (UTA)","contentLocale":"vi","term":"Tài khoản giao dịch hợp nhất (UTA)","aka":["UTA","unified trading account","tài khoản hợp nhất","tài khoản thống nhất"],"short":"Tài khoản giao dịch hợp nhất là loại tài khoản gộp spot, ký quỹ, hợp đồng tương lai và quyền chọn vào một ví duy nhất, cho phép dùng chung tài sản làm ký quỹ.","body":["Trước đây, bạn phải chuyển tiền qua lại giữa ví spot và ví futures. Với UTA, như trên Bybit hay chế độ tài khoản đa tiền tệ của OKX, mọi tài sản nằm chung một nơi và được quy đổi thành giá trị ký quỹ. Lãi từ một vị thế có thể bù lỗ cho vị thế khác.",["Mỗi tài sản được tính ký quỹ theo một tỷ lệ chiết khấu. ",["Stablecoin","stablecoin"]," thường được tính gần như toàn bộ, còn ",["BTC","bitcoin"],", ",["ETH","ethereum"]," và ",["altcoin","altcoin"]," bị chiết khấu nhiều hơn tùy ",["độ biến động","volatility"]," và ",["thanh khoản","liquidity"],". Một số chế độ còn tính ký quỹ theo rủi ro tổng danh mục."],"Tiện lợi đi kèm rủi ro: khi dùng ký quỹ chéo, một vị thế lỗ nặng có thể kéo cả tài sản spot vào nguy cơ thanh lý. Tên gọi, tỷ lệ chiết khấu và chế độ ký quỹ khác nhau giữa các sàn."],"example":"Giả sử trong UTA bạn có 0,1 BTC trị giá 6.000 USDT khi BTC giá 60.000 và 2.000 USDT. Nếu sàn tính BTC ở tỷ lệ 95%, giá trị ký quỹ của bạn là 5.700 cộng 2.000, tức 7.700 USDT. Bạn mở long ETH dùng ký quỹ này. Nếu BTC giảm 20% xuống 48.000, phần BTC chỉ còn tương đương 4.560 USDT ký quỹ, tổng ký quỹ giảm còn 6.560 USDT dù vị thế ETH không đổi, và nguy cơ thanh lý tăng lên.","mistakes":["Quên rằng coin spot trong UTA đang được dùng làm ký quỹ cho vị thế futures.","Bỏ qua tỷ lệ chiết khấu ký quỹ của altcoin.","Bật ký quỹ chéo cho toàn tài khoản khi chỉ muốn rủi ro giới hạn trong một lệnh."],"faq":[{"q":"UTA có tốt hơn tài khoản tách riêng không?","a":"UTA giúp dùng vốn hiệu quả và không cần chuyển ví, nhưng rủi ro lan sang toàn tài khoản. Nếu muốn tách biệt rủi ro, hãy dùng ký quỹ cô lập hoặc tài khoản phụ."},{"q":"Có thể dùng BTC làm ký quỹ cho hợp đồng USDT không?","a":"Trong UTA thường là có, BTC được quy đổi thành giá trị ký quỹ sau khi trừ tỷ lệ chiết khấu. Hãy xem bảng tỷ lệ trên sàn bạn dùng."}],"title":"Tài khoản giao dịch hợp nhất (UTA) là gì?","description":"UTA gộp spot, futures và quyền chọn vào một tài khoản ký quỹ chung. Tìm hiểu tỷ lệ chiết khấu, lợi ích và rủi ro thanh lý.","related":[["cross-margin","Ký quỹ chéo (Cross margin)","Ký quỹ chéo là chế độ trong đó toàn bộ số dư khả dụng của tài khoản được dùng chung làm ký quỹ cho các vị thế, giúp hạn chế thanh lý sớm nhưng có thể khiến bạn mất cả tài khoản."],["portfolio-margin","Ký quỹ danh mục (Portfolio margin)","Ký quỹ danh mục là chế độ tính ký quỹ dựa trên rủi ro tổng thể của cả danh mục, cho phép các vị thế phòng hộ lẫn nhau được giảm yêu cầu ký quỹ."],["sub-account","Tài khoản phụ (sub-account)","Tài khoản phụ là tài khoản con được tạo dưới tài khoản chính trên sàn, có số dư và vị thế riêng, giúp bạn tách biệt chiến lược, rủi ro và quyền truy cập."],["margin-trading","Giao dịch ký quỹ (Margin trading)","Giao dịch ký quỹ là việc vay thêm vốn từ sàn, dùng tài sản của bạn làm tài sản đảm bảo, để mở vị thế lớn hơn số tiền bạn có."]],"lesson":null,"coin":null,"tool":null,"cta":true},"withdrawal-fee":{"slug":"withdrawal-fee","cat":"exchange-features","en":"Withdrawal fee","contentLocale":"vi","term":"Phí rút tiền (withdrawal fee)","aka":["phí rút","withdrawal fee","phí rút coin","phí chuyển mạng"],"short":"Phí rút tiền là khoản phí sàn thu khi bạn chuyển crypto từ tài khoản sàn ra ví hoặc sàn khác, thường là một số coin cố định tùy theo mạng blockchain bạn chọn.","body":[["Phí rút chủ yếu để bù ",["phí gas","gas-fee"]," mà sàn phải trả cho ",["blockchain","blockchain"],". Vì vậy cùng một đồng ",["USDT","usdt"],", rút qua mạng ",["Ethereum","ethereum"]," thường đắt hơn nhiều so với rút qua TRON, BNB Chain, Solana hay các mạng ",["layer 2","layer-2"]," như Arbitrum. Sàn có thể cập nhật phí theo tình trạng mạng."],"Phí rút thường là con số cố định chứ không theo phần trăm, nên rút số tiền nhỏ nhiều lần sẽ tốn hơn rút một lần. Ngoài ra còn có số tiền rút tối thiểu. Một số sàn miễn phí chuyển nội bộ giữa người dùng cùng sàn.","Điều quan trọng nhất là chọn đúng mạng mà ví hoặc sàn nhận hỗ trợ. Chọn sai mạng có thể khiến tiền bị thất lạc và rất khó lấy lại."],"example":"Giả sử bạn muốn chuyển 300 USDT sang một sàn khác. Sàn gửi báo phí rút 1 USDT qua TRC20, 0,8 USDT qua BEP20 và 4 USDT qua ERC20. Nếu sàn nhận hỗ trợ cả ba, chọn BEP20 giúp bạn nhận 299,2 USDT thay vì 296 USDT qua ERC20. Nếu bạn chia khoản này thành năm lần rút 60 USDT qua ERC20, tổng phí sẽ là 20 USDT, gấp năm lần một lần rút.","mistakes":["Chọn mạng chỉ vì phí rẻ mà không kiểm tra ví hoặc sàn nhận có hỗ trợ mạng đó.","Rút nhiều lần với số tiền nhỏ, khiến tổng phí cố định tăng lên.","Quên điền memo hoặc tag khi rút các coin yêu cầu trường này."],"faq":[{"q":"Mạng nào rút USDT rẻ nhất?","a":"Thường là các mạng phí thấp như TRON, BNB Chain, Solana hoặc layer 2, nhưng phí do từng sàn đặt và thay đổi theo thời gian. Hãy xem màn hình rút tiền trước mỗi lần chuyển."},{"q":"Vì sao phí rút cố định chứ không theo phần trăm?","a":"Vì chi phí gas của blockchain phụ thuộc vào giao dịch chứ không phụ thuộc vào số tiền. Rút 10 hay 10.000 USDT qua cùng mạng thường tốn gas tương tự."}],"title":"Phí rút tiền là gì? Cách giảm phí rút crypto","description":"Phí rút là khoản sàn thu khi chuyển crypto ra ngoài. So sánh phí theo mạng, cách chọn mạng đúng và mẹo giảm tổng phí rút.","related":[["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."],["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng."],["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."],["layer-2","Layer 2 (L2, giải pháp lớp 2)","Layer 2 (L2) là mạng xây trên một blockchain lớp 1, xử lý giao dịch bên ngoài chuỗi chính rồi gửi kết quả gom lại về L1, giúp giao dịch nhanh hơn và phí rẻ hơn."]],"lesson":{"id":"E08","slug":"sell-vs-withdraw","ep":8,"title":"Tôi đã bán rồi. Tại sao tiền vẫn chưa về tài khoản ngân hàng?"},"coin":null,"tool":"/rates","cta":false}});
